    const PEARL_HI = [["0", "#ffffff"], [".6", "#fdfcfa"], ["1", "#f3f1ec"]];
    const PEARL_LO = [["0", "#9a958e"], [".6", "#7d7872"], ["1", "#64605b"]];
    const GOLD = [["0", "#fff3d2"], [".3", "#f3dcab"], [".5", "#ddb776"], [".66", "#b3843f"], [".76", "#976525"], [".88", "#c39650"], ["1", "#e2bf7f"]];
    const GOLD_HI = [["0", "#fffaf0"], [".6", "#fff1d6"], ["1", "#f7e3b8"]];
